sys-handoff-protocols.example:
Customer-support multi-agent: triage agent, затем specialist agent, затем escalation если нужна.

```python
@dataclass
class Handoff:
    from_agent: str
    to_agent: str
    trace_id: str
    task: str
    context: dict
    completed: list
    constraints: dict
    artifacts: dict

def triage_agent(ticket):
    classification = classify(ticket)  # см. branching logic
    return Handoff(
        from_agent="triage",
        to_agent=f"specialist_{classification.category}",
        trace_id=ticket.id,
        task=f"Resolve {classification.category} ticket #{ticket.id}",
        context={
            "ticket_summary": summarize(ticket, max_tokens=300),
            "customer_tier": ticket.customer.tier,
            "previous_tickets": ticket.customer.recent_tickets[:5],  # not all 200
        },
        completed=[{"step": "triage", "result": classification.to_dict()}],
        constraints={
            "max_response_time_hours": 4 if ticket.customer.tier == "enterprise" else 24,
            "tone": "professional",
        },
        artifacts={"full_ticket": ticket.id}  # reference, not embed
    )

def specialist_agent(handoff: Handoff):
    # Receives compact handoff, can pull full ticket if needed
    response = generate_response(handoff)
    if response.confidence < 0.8:  # см. confidence thresholds
        return escalate(handoff)
    return resolve(handoff, response)
```

Metrics: handoff payload size (norm < 5k tokens), handoff success rate (norm > 95%), re-work rate (specialist спросил то же что triage).

sys-tool-orchestration.example:
AI sales assistant с tools: `crm_lookup`, `email_history`, `meeting_calendar`, `linkedin_fetch`, `send_email`.

```python
TOOLS = [
    {
        "name": "crm_lookup",
        "description": "Fetch CRM record for a company or contact by ID. "
                       "Use when you need deal stage, account owner, revenue. "
                       "Do NOT use for searching — use crm_search instead.",
        "input_schema": {...}
    },
    {
        "name": "email_history",
        "description": "Fetch last 20 emails with a contact. Independent of crm_lookup — "
                       "can be called in parallel.",
        "input_schema": {...}
    },
    # ... etc
]

SYSTEM_PROMPT = """You are a sales assistant. When you need data from multiple tools
and they are independent, CALL THEM IN PARALLEL in a single turn.
Max 8 tool calls per task. If a tool fails twice, skip it and note in response."""

MAX_TOOL_CALLS = 8

def agent_loop(query):
    tool_count = 0
    messages = [{"role": "user", "content": query}]
    while True:
        r = client.messages.create(model="sonnet-4-5", tools=TOOLS, messages=messages)
        if r.stop_reason == "end_turn":
            return r
        tool_calls = [b for b in r.content if b.type == "tool_use"]
        tool_count += len(tool_calls)
        if tool_count > MAX_TOOL_CALLS:
            return fail("tool budget exceeded")

        # Execute in parallel
        tool_results = await asyncio.gather(*[execute(tc) for tc in tool_calls])
        messages.extend([
            {"role": "assistant", "content": r.content},
            {"role": "user", "content": tool_results}
        ])
```

Result: agent typically делает 1 parallel-turn (3-4 tools) + 1 final-turn вместо 4 sequential turns. Latency 2s вместо 8s.

sys-batch-vs-realtime.example:
B2B AI-CRM: классификация лидов + email-draft generation.

**Architecture decision:**
- New lead arrives, затем realtime AI-score (sales rep видит immediately в UI)
- Email drafts для outreach campaign — batch (overnight)
- Weekly account scoring update — batch
- Sales rep asks AI question in chat — realtime + streaming

```python
# Realtime: lead scoring
@api.post("/lead-created")
async def score_lead(lead):
    score = await sonnet_call(SCORE_PROMPT, lead)  # < 2s
    return {"score": score, "tier": tier_for(score)}

# Batch: nightly outreach drafts
def nightly_outreach_drafts():
    leads = db.query("SELECT * FROM leads WHERE outreach_due_at < tomorrow()")
    batch = client.messages.batches.create(
        requests=[
            {"custom_id": f"lead-{l.id}", "params": {
                "model": "claude-sonnet-4-5-20250929",
                "messages": [{"role": "user", "content": DRAFT_PROMPT + l.context}],
                "max_tokens": 500,
            }}
            for l in leads
        ]
    )
    # Cron checks batch status next morning

@cron("0 7 * * *")
def pickup_batch_results():
    for batch in pending_batches():
        if batch.processing_status == "ended":
            for result in client.messages.batches.results(batch.id):
                save_draft(result.custom_id, result.message.content)
            mark_complete(batch.id)

# Streaming: interactive chat
@api.post("/chat")
async def chat(message):
    async def stream():
        async with client.messages.stream(...) as s:
            async for text in s.text_stream:
                yield text
    return StreamingResponse(stream())
```

Result: $X/month savings vs all-realtime, realtime UX preserved для critical paths.

sys-data-sync.example:
AI sales assistant с context из Salesforce + Linear + Slack.

```python
# 1. Webhook listeners
@webhook("/salesforce/opportunity-changed")
def on_opp_changed(event):
    sync_queue.enqueue({
        "source": "salesforce", "entity": "opportunity",
        "id": event.id, "trigger": "webhook"
    })

# 2. Polling fallback (every 5 min, catches missed webhooks)
@cron("*/5 * * * *")
def poll_salesforce():
    cursor = get_cursor("salesforce", "opportunity")
    new = sf.query(f"SELECT Id FROM Opportunity WHERE LastModifiedDate > {cursor} LIMIT 200")
    for opp in new:
        sync_queue.enqueue({"source": "salesforce", "entity": "opportunity",
                            "id": opp.Id, "trigger": "polling"})
    set_cursor("salesforce", "opportunity", now())

# 3. Sync worker — pulls full record, normalizes, upserts to AI store
def sync_worker(msg):
    record = sf.fetch(msg.id)  # or linear.fetch, etc
    normalized = normalize(record, source=msg.source)
    operational_store.upsert(
        table=f"{msg.source}_{msg.entity}",
        id=normalized.id,
        data=normalized,
        synced_at=now()
    )

# 4. AI agent queries local store (fast)
def agent_context_for(deal_id):
    opp = operational_store.fetch("salesforce_opportunity", deal_id)
    related_tickets = operational_store.query("linear_issue", deal_id=deal_id)
    slack_threads = operational_store.query("slack_thread", deal_id=deal_id)
    return assemble_context(opp, related_tickets, slack_threads)

# 5. Weekly drift check
@cron("0 3 * * SUN")
def weekly_full_sync():
    for source in SOURCES:
        for entity in source.entities:
            full_sync(source, entity)  # reconcile, log drift
```

Metrics: sync lag per source (norm < 15min p95), drift count from weekly sync (norm < 0.1%), webhook delivery rate (alert if < 95%).

sys-auth-patterns.example:
B2B SaaS: AI ассистент подключается к Gmail клиента через OAuth.

```python
# 1. OAuth flow initiation
@api.post("/connect/gmail")
def initiate_gmail_oauth(user):
    state = generate_csrf_state()
    save_state(state, user.id)
    url = build_oauth_url(
        provider="gmail",
        scopes=["gmail.readonly", "gmail.compose"],  # minimal — NOT full_access
        state=state,
        pkce_verifier=...,
    )
    return {"redirect_url": url}

# 2. Callback — exchange code for tokens
@api.get("/oauth/gmail/callback")
def oauth_callback(code, state):
    user_id = verify_state(state)
    tokens = exchange_code_for_tokens(code, pkce_verifier=...)
    # tokens: {access_token, refresh_token, expires_in: 3600}

    secrets_manager.put(
        path=f"oauth/gmail/{user_id}",
        value={
            "access_token": tokens.access_token,
            "refresh_token": tokens.refresh_token,  # encrypted at rest
            "expires_at": now() + seconds(tokens.expires_in),
            "scopes": tokens.scope.split(),
        }
    )
    log_audit({"event": "oauth_grant", "user_id": user_id, "provider": "gmail", "scopes": tokens.scope})

# 3. AI agent uses token (with refresh)
def gmail_call(user_id, operation):
    creds = secrets_manager.get(f"oauth/gmail/{user_id}")

    if creds.expires_at < now() + minutes(5):
        creds = refresh_token(creds)
        secrets_manager.put(...)  # rotated refresh_token too

    log_audit({"event": "gmail_api_call", "user_id": user_id, "operation": operation})
    return gmail_api(token=creds.access_token, op=operation)

# 4. Revocation (user disconnects or leaves)
@api.post("/disconnect/gmail")
def revoke_gmail(user):
    creds = secrets_manager.get(f"oauth/gmail/{user.id}")
    gmail_api.revoke(creds.refresh_token)  # revoke at provider
    secrets_manager.delete(f"oauth/gmail/{user.id}")
    log_audit({"event": "oauth_revoke", "user_id": user.id, "provider": "gmail"})
```

Metrics: failed auth rate (alert > 1%), token rotation success rate, scope-creep (alert if new scope granted).

sys-error-handling.example:
B2B AI-chatbot.

```python
class AIResponseError(Exception): pass

async def get_ai_response(user_query, context, user_id):
    fallback_chain = [
        ("primary", primary_call),
        ("reduced_context", lambda: primary_call_with_reduced_context(context, last_n=3)),
        ("haiku_fallback", lambda: haiku_call(user_query, context)),
        ("semantic_cache", lambda: semantic_cache.lookup(user_query)),
        ("canned", lambda: canned_response()),
    ]

    for strategy_name, strategy in fallback_chain:
        try:
            timeout = 5 if strategy_name == "primary" else 3
            result = await asyncio.wait_for(strategy(), timeout=timeout)

            # Validate output
            if not is_valid_response(result):
                raise AIResponseError(f"invalid output from {strategy_name}")

            log_strategy_used(user_id, strategy_name)
            if strategy_name != "primary":
                metrics.increment(f"fallback.used.{strategy_name}")

            return result

        except (RateLimitError, TimeoutError, ServerError) as e:
            log_warning(f"{strategy_name} failed: {e}")
            continue  # try next strategy

        except RefusalError as e:
            # Don't fall back — refusal is intentional
            return user_friendly_refusal(e)

    # All fallbacks exhausted
    metrics.increment("fallback.exhausted")
    log_incident({"user_id": user_id, "query": user_query, "context": context})
    return canned_response()  # last resort

# Tool-level: agent with partial response
async def agent_with_tools(query):
    tool_results = {}
    for tool in selected_tools:
        try:
            tool_results[tool.name] = await tool.execute(timeout=3)
        except Exception as e:
            tool_results[tool.name] = {"error": str(e), "skipped": True}
            log_warning(f"tool {tool.name} failed")

    if all(r.get("skipped") for r in tool_results.values()):
        return fallback_response("all tools unavailable")

    return synthesize_response(query, tool_results,
        note=f"Note: {sum(r.get('skipped', False) for r in tool_results.values())} sources unavailable")
```

Metrics: success rate per strategy, fallback distribution (norm: 95% primary), full-exhaustion rate (alert > 0.1%).
